"""Documentation checks: relative links resolve, tables keep their column count, Part B 10.4 matches the records."""
import csv
import json
import re
import sys
from pathlib import Path

root = Path(sys.argv[1])
files = [root / "README.md", root / "docs/spec.md", root / "docs/recovery-part-a.md", root / "docs/recovery-part-b.md"]
problems = 0

for f in files:
    text = f.read_text()
    for target in re.findall(r"\]\(([^)#\s]+)(?:#[^)]*)?\)", text):
        if target.startswith(("http://", "https://", "mailto:")):
            continue
        if not (f.parent / target).exists():
            problems += 1
            print(f"{f.name}: broken link {target}")
    lines = text.splitlines()
    for i, line in enumerate(lines):
        if re.fullmatch(r"\|(\s*:?-{3,}:?\s*\|)+", line.strip()):
            width = lines[i - 1].count("|")
            j = i + 1
            while j < len(lines) and lines[j].startswith("|"):
                if lines[j].count("|") != width:
                    problems += 1
                    print(f"{f.name}:{j + 1}: {lines[j].count('|') - 1} cells, header has {width - 1}")
                j += 1
print("links and tables checked in", len(files), "files")

# Part B 10.4 against the records
folder = root / "data/outputs-recovery/formal/batch-3"
read = lambda p: [json.loads(line) for line in p.read_text().splitlines() if line.strip()]
harness = read(folder / "harness.jsonl")
workers = read(folder / "events/A.jsonl") + read(folder / "events/B.jsonl")
deadlines = {e["job_id"]: e for e in harness if e["event"] == "deadline"}
injections = {e["job_id"]: e for e in harness if e["event"] == "injection"}
accepted = {}
for e in workers:
    if e["event"] == "accepted":
        accepted[e["job_id"]] = min(accepted.get(e["job_id"], e["mono"]), e["mono"])
csv_rows = {int(r["position"]): r for r in csv.DictReader(open(folder / "injections.csv"))}

part_b = (root / "docs/recovery-part-b.md").read_text()
section = part_b[part_b.index("### 10.4"):part_b.index("### 10.5")]
table = [line for line in section.splitlines() if re.match(r"\| \d+ \|", line)]
assert len(table) == 30, len(table)


def same(doc: str, value) -> bool:
    if value is None:
        return not re.fullmatch(r"−?\d+\.\d", doc)
    return doc.replace("−", "-") == f"{value:.1f}" or (doc in ("−0.0", "0.0") and abs(value) < 0.05)


for line in table:
    cells = [c.strip() for c in line.strip("|").split("|")]
    position, case = int(cells[0]), cells[1]
    r = csv_rows[position]
    job = int(r["job_id"])
    d, inj, acc = deadlines[job], injections.get(job, {}), accepted.get(job)
    num = lambda x: float(x) if re.fullmatch(r"-?\d+(\.\d+)?", x or "") else None
    expected = {
        2: num(r["detection_s"]), 3: num(r["rerun_s"]),
        4: acc - d["t_submit"] if acc else None,
        5: acc - inj["t_inj"] if acc and inj.get("t_inj") and case not in ("C0", "W5a", "W5b") else None,
        7: acc - d["reference_mono"] if acc and case not in ("W5a", "W5b") else None,
        8: d["deadline_s"],
        9: d["deadline_mono"] - acc if acc and case not in ("W5a", "W5b") else None,
    }
    if case != r["case"]:
        problems += 1
        print(f"position {position}: case {case} != {r['case']}")
    for col, value in expected.items():
        doc = cells[col].replace("**", "")
        if col == 8:
            ok = float(doc) == value
        else:
            ok = same(doc, value)
        if not ok:
            problems += 1
            print(f"position {position} ({case}) column {col}: document {doc!r}, records {value}")
    deadline = "on time" if r["timeliness"] == "on time" and r["deadline_met"] == "yes" else r["timeliness"]
    if cells[10] != deadline:
        problems += 1
        print(f"position {position}: deadline {cells[10]!r} != {deadline!r}")
    if "return" in cells[6]:
        outage = float(re.search(r"(\d+\.\d) s after", cells[6]).group(1))
        if f"{inj['restored'] - inj['t_inj']:.1f}" != f"{outage:.1f}":
            problems += 1
            print(f"position {position}: outage {outage} != {inj['restored'] - inj['t_inj']:.2f}")
print("Part B 10.4: 30 rows checked against harness.jsonl, the worker events and injections.csv")
print("problems:", problems)
sys.exit(1 if problems else 0)

